export async function setIssueMilestone(
  orgId: OrgId,
  issueId: IssueId,
  milestoneId: MilestoneId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ milestoneId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  const labels = await listLabelsForIssues(orgId, [row.id as IssueId]);
  return toIssue(row, (labels[row.id] ?? []).map((label) => label.id));
}

/** Every issue (archived included) currently in one of the given milestones. */
export async function listIssuesInMilestones(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<readonly Issue[]> {
  if (milestoneIds.length === 0) return [];
  return getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        inArray(issues.milestoneId, [...milestoneIds]),
      ),
    )
    .all()
    .map((row) => toIssue(row));
}

/** Moves the given issues into `milestoneId` (or out of any milestone). */
export async function moveIssuesToMilestone(
  orgId: OrgId,
  issueIds: readonly IssueId[],
  milestoneId: MilestoneId | null,
): Promise<void> {
  if (issueIds.length === 0) return;
  getDb()
    .update(issues)
    .set({ milestoneId, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])),
    )
    .run();
}
EOF
