export async function insertMilestone(
  input: CreateMilestoneInput,
): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name.trim(),
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: {
    name?: string;
    targetDate?: IsoTimestamp | null;
    closedAt?: IsoTimestamp | null;
  },
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}
