/**
 * Project milestones: lifecycle, the open-milestone cap, per-project name
 * uniqueness, progress and the close cascade that moves open issues on.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError, normalizeMilestoneName } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type {
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";
import type { Project } from "@/types/project";

async function loadProject(orgId: OrgId, projectId: ProjectId): Promise<Project> {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
}

async function loadMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<{ milestone: Milestone; project: Project }> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await loadProject(orgId, milestone.projectId);
  return { milestone, project };
}

function isOpenIssue(issue: Issue): boolean {
  return issue.archivedAt === null && !CLOSED_ISSUE_STATUSES.includes(issue.status);
}

function assertNameFree(
  siblings: readonly Milestone[],
  name: string,
  selfId: MilestoneId | null,
): void {
  const wanted = normalizeMilestoneName(name);
  const taken = siblings.some(
    (other) =>
      other.id !== selfId && normalizeMilestoneName(other.name) === wanted,
  );
  if (taken) throw new MilestoneStateError("name_taken", selfId);
}

function assertRoomForOpen(
  siblings: readonly Milestone[],
  selfId: MilestoneId | null,
): void {
  const open = siblings.filter(
    (other) => other.closedAt === null && other.id !== selfId,
  ).length;
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open", selfId);
  }
}

/**
 * Resolves a milestone an issue of `projectId` may be put into: it must exist
 * in this workspace and project, and be open.
 */
export async function requireOpenMilestoneForProject(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const milestone = await milestoneRepo.findMilestoneById(orgId, milestoneId);
  if (milestone === null || milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed", milestone.id);
  }
  return milestone;
}

function withProgress(
  milestone: Milestone,
  issues: readonly Issue[],
  now: Date,
): MilestoneWithProgress {
  const live = issues.filter(
    (issue) => issue.milestoneId === milestone.id && issue.archivedAt === null,
  );
  const open = live.filter(isOpenIssue).length;
  const progress: MilestoneProgress = {
    total: live.length,
    open,
    closed: live.length - open,
  };
  const overdue =
    milestone.closedAt === null &&
    milestone.targetDate !== null &&
    new Date(milestone.targetDate).getTime() < now.getTime() &&
    open > 0;
  return { milestone, progress, overdue };
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = await loadProject(input.orgId, input.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const siblings = await milestoneRepo.listMilestonesForProject(
    input.orgId,
    project.id,
  );
  assertNameFree(siblings, input.name, null);
  assertRoomForOpen(siblings, null);

  const milestone = await milestoneRepo.insertMilestone(input);

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const { milestone, project } = await loadMilestone(
    input.orgId,
    input.milestoneId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.name !== undefined) {
    const siblings = await milestoneRepo.listMilestonesForProject(
      input.orgId,
      project.id,
    );
    assertNameFree(siblings, input.name, milestone.id);
  }

  return milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    ...(input.name === undefined ? {} : { name: input.name.trim() }),
    ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
  });
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const { milestone, project } = await loadMilestone(
    input.orgId,
    input.milestoneId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed", milestone.id);
  }

  const targetId = input.moveOpenIssuesTo;
  if (targetId !== null) {
    if (targetId === milestone.id) {
      throw new NotFoundError("Milestone", targetId);
    }
    await requireOpenMilestoneForProject(input.orgId, project.id, targetId);
  }

  const issues = await issueRepo.listIssuesInMilestones(input.orgId, [
    milestone.id,
  ]);
  const movedIssueIds = issues.filter(isOpenIssue).map((issue) => issue.id);

  await issueRepo.moveIssuesToMilestone(input.orgId, movedIssueIds, targetId);
  const closed = await milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    closedAt: toIsoTimestamp(new Date()),
  });

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: targetId,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const { milestone, project } = await loadMilestone(orgId, milestoneId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt === null) {
    throw new MilestoneStateError("already_open", milestone.id);
  }

  const siblings = await milestoneRepo.listMilestonesForProject(
    orgId,
    project.id,
  );
  assertRoomForOpen(siblings, milestone.id);

  const reopened = await milestoneRepo.updateMilestone(orgId, milestone.id, {
    closedAt: null,
  });

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

function compareMilestones(a: Milestone, b: Milestone): number {
  const aClosed = a.closedAt === null ? 0 : 1;
  const bClosed = b.closedAt === null ? 0 : 1;
  if (aClosed !== bClosed) return aClosed - bClosed;

  if (a.targetDate !== b.targetDate) {
    if (a.targetDate === null) return 1;
    if (b.targetDate === null) return -1;
    const diff =
      new Date(a.targetDate).getTime() - new Date(b.targetDate).getTime();
    if (diff !== 0) return diff;
  }

  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = await loadProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const milestones = [
    ...(await milestoneRepo.listMilestonesForProject(orgId, project.id)),
  ].sort(compareMilestones);
  const issues = await issueRepo.listIssuesInMilestones(
    orgId,
    milestones.map((milestone) => milestone.id),
  );
  const now = new Date();

  return milestones.map((milestone) => withProgress(milestone, issues, now));
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const { milestone, project } = await loadMilestone(orgId, milestoneId);
  assertCan(actor, "project:read", projectResource(project));

  const issues = await issueRepo.listIssuesInMilestones(orgId, [milestone.id]);
  return withProgress(milestone, issues, new Date());
}
