  const targetId = input.moveOpenIssuesTo;
  if (targetId !== null) {
    if (targetId === milestone.id) {
      throw new NotFoundError("Milestone", targetId);
    }
    await requireOpenMilestoneForProject(input.orgId, project.id, targetId);
  }

  const issues = await issueRepo.listIssuesInMilestones(input.orgId, [
    milestone.id,
  ]);
  const movedIssueIds = issues.filter(isOpenIssue).map((issue) => issue.id);

  await issueRepo.moveIssuesToMilestone(input.orgId, movedIssueIds, targetId);
  const closed = await milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    closedAt: toIsoTimestamp(new Date()),
  });

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: targetId,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const { milestone, project } = await loadMilestone(orgId, milestoneId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt === null) {
    throw new MilestoneStateError("already_open", milestone.id);
  }

  const siblings = await milestoneRepo.listMilestonesForProject(
    orgId,
    project.id,
  );
  assertRoomForOpen(siblings, milestone.id);

  const reopened = await milestoneRepo.updateMilestone(orgId, milestone.id, {
    closedAt: null,
  });

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

function compareMilestones(a: Milestone, b: Milestone): number {
  const aClosed = a.closedAt === null ? 0 : 1;
  const bClosed = b.closedAt === null ? 0 : 1;
  if (aClosed !== bClosed) return aClosed - bClosed;

  if (a.targetDate !== b.targetDate) {
    if (a.targetDate === null) return 1;
    if (b.targetDate === null) return -1;
    const diff =
      new Date(a.targetDate).getTime() - new Date(b.targetDate).getTime();
    if (diff !== 0) return diff;
  }

  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = await loadProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const milestones = [
    ...(await milestoneRepo.listMilestonesForProject(orgId, project.id)),
  ].sort(compareMilestones);
  const issues = await issueRepo.listIssuesInMilestones(
    orgId,
    milestones.map((milestone) => milestone.id),
  );
  const now = new Date();

  return milestones.map((milestone) => withProgress(milestone, issues, now));
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const { milestone, project } = await loadMilestone(orgId, milestoneId);
  assertCan(actor, "project:read", projectResource(project));

  const issues = await issueRepo.listIssuesInMilestones(orgId, [milestone.id]);
  return withProgress(milestone, issues, new Date());
}
